/// <summary>
/// MPJ_34165_SalesOrderGuideCustomAPI
/// Service class to check if an item is orderbale for a given customer.
/// </summary>
class METSalesOrderGuideService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// determines if an item is orderable for a given customer
    /// </summary>
    /// <param name = "_contract"><c>METSalesOrderGuideRequestCollectionContract</c></param>
    /// <returns>reponse as a data contract <c>MESalesOrderGuideResponseCollectionContract</c> </returns>
    public METSalesOrderGuideResponseCollectionContract isOnOrderGuide(METSalesOrderGuideRequestCollectionContract _contract)
    {
        METSalesOrderGuideRequestContract   request;
        List                                responseList = new List(Types::Class);
        ListEnumerator                      itemListEnumerator = _contract.parmItemList().getEnumerator();
        ItemId                              itemId;
        CustAccount                         custAccount;
        boolean                             isOrderable;
        METSalesOrderGuideResponseCollectionContract response = new METSalesOrderGuideResponseCollectionContract();

        changecompany(_contract.parmDataAreaId())
        {
            custAccount = _contract.parmCustAccount();

            while(itemListEnumerator.moveNext())
            {
                METSalesOrderGuideResponseContract responseContract = new METSalesOrderGuideResponseContract();
                request = itemListEnumerator.current();
                
                itemId = request.parmItemId();
                isOrderable = METSalesOrderGuideExecution::isItemOrderable(custAccount, itemId);
                
                responseContract.parmIsOnOrderGuide(isOrderable);
                responseContract.parmItemId(itemId);
                
                responseList.addEnd(responseContract);
            }
        }
        response.parmCustAccount(custAccount);
        response.parmSalesOrderGuideResponseList(responseList);

        return response;
    }
